  public static double PanelScale(double width,double height,Rect area){return Math.Min(1,Math.Min(Math.Max(120,area.Width-16)/width,Math.Max(120,area.Height-16)/height));}
  void FitPanel(Window w,double height){var box=w.Content as Viewbox;if(box==null)return;var design=box.Child as FrameworkElement;if(design==null)return;design.Height=height;Rect area=pet.WorkArea();double scale=PanelScale(design.Width,height,area);w.Width=design.Width*scale;w.Height=height*scale;if(!double.IsNaN(w.Left))w.Left=Math.Max(area.Left+8,Math.Min(area.Right-w.Width-8,w.Left));if(!double.IsNaN(w.Top))w.Top=Math.Max(area.Top+8,Math.Min(area.Bottom-w.Height-8,w.Top));}
  Pane Panel(string title,double width,double height,bool transient=false){
   if(!transient&&Current!=null){var old=Current;Current=null;old.Close();}
   var w=new Window{Title=title,Width=width,Height=height,WindowStyle=WindowStyle.None,AllowsTransparency=true,Background=null,ResizeMode=ResizeMode.NoResize,Topmost=pet.Config.Topmost,ShowInTaskbar=false,Owner=pet};
   var border=new Border{Width=width,Height=height,CornerRadius=new CornerRadius(20),Background=new SolidColorBrush(Color.FromArgb(244,249,251,243)),BorderBrush=new SolidColorBrush(Color.FromArgb(170,186,206,173)),BorderThickness=new Thickness(1),Padding=new Thickness(17)};
   var grid=new Grid();grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});
   var head=new DockPanel();var close=Button("×",()=>w.Close());DockPanel.SetDock(close,Dock.Right);head.Children.Add(close);var label=Text(title,20);label.FontWeight=FontWeights.SemiBold;label.MouseLeftButtonDown+=(s,e)=>{if(e.ButtonState==MouseButtonState.Pressed)w.DragMove();};head.Children.Add(label);grid.Children.Add(head);
   var body=new StackPanel{Margin=new Thickness(0,7,0,0)};var scroll=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};Grid.SetRow(scroll,1);grid.Children.Add(scroll);border.Child=grid;w.Content=new Viewbox{Child=border,Stretch=Stretch.Uniform};FitPanel(w,height);
   var area=pet.WorkArea();w.Left=Math.Max(area.Left+8,Math.Min(area.Right-w.Width-8,pet.Left+pet.Width/2-w.Width/2));w.Top=Math.Max(area.Top+8,Math.Min(area.Bottom-w.Height-8,pet.Top-w.Height+100));
   w.KeyDown+=(s,e)=>{if(e.Key==Key.Escape)w.Close();};if(!transient){Current=w;pet.Busy=true;w.Closed+=(s,e)=>{if(Current==w){Current=null;pet.Busy=false;}pet.Persist();};}
   return new Pane{Win=w,Body=body};
  }
